import{z as s,x as p,o as i,c as B,q as l,j as o,D as e,d as t,s as n,S as A,b as E}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"光瞳滤波与切趾","description":"","frontmatter":{"title":"光瞳滤波与切趾","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/pupil-apodization.md","filePath":"litho/pupil-apodization.md","lastUpdated":1791063341000}'),h={name:"litho/pupil-apodization.md"};function d(m,a,c,P,f,D){const r=p("Mermaid");return i(),B("div",null,[a[2]||(a[2]=l('<h1 id="光瞳滤波与切趾" tabindex="-1">光瞳滤波与切趾 <a class="header-anchor" href="#光瞳滤波与切趾" aria-label="Permalink to &quot;光瞳滤波与切趾&quot;">​</a></h1><div class="epigraph"><p>阿贝的光瞳可以不是砖墙：通带里的振幅沿径向再调制，旁瓣与主瓣一起改形状，这叫切趾，不是又一种缩比。</p><footer>—— Born &amp; Wolf 对切趾的讨论；光刻光瞳滤波见 Mack, Fundamental Principles of Optical Lithography</footer></div><p><a href="/litho/abbe-imaging">上一课</a>把成像收成物频谱乘光瞳 \\(P(\\mathbf{f})\\)，并默认理想圆孔是硬切：通带内振幅为 1、带外为 0。缺口是：<strong>通带内部的 \\(|P|\\) 仍可以随光瞳坐标变</strong>。相位留给后面的像差课；本课只动振幅。数值孔径如何把这扇窗的半径写成 \\(n\\sin\\theta\\)，留给<a href="/litho/lens-na">透镜与数值孔径</a>。不要把切趾写成 RET 产品目录，也不要从 \\(k_1\\) 起笔。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>硬切光瞳的相干点扩散是艾里一类核：中心瓣之外有环带。环带把能量送到不该亮的地方，相干旁瓣、孔周围的振铃都与此有关。若把 \\(|P(\\rho)|\\) 从中心向边缘逐渐压低（切趾），傅里叶核的旁瓣下降，主瓣变宽——分辨率与杂讯之间换权重。反过来，中心遮拦或边缘加重会抬高频、也抬旁瓣。缺口因此是光瞳上的<strong>振幅滤波</strong>，而不是再讲一遍「级次要进窗」。</p><p>阿贝已经允许 \\(P\\) 为复透过率。本课把模与辐角拆开：模是切趾 / 遮拦 / 高斯衰减；辐角是离焦与 Zernike，后课再展开。</p><p><span class="marginnote">「切趾」直译是「给脚趾修形」：硬边光瞳像一个矩形「脚」，衍射在它上面磨出振铃。把边缘磨圆、按半径加权，就叫切趾——和信号处理里的窗函数是同一件事，只是这扇窗开在光瞳上。</span></p><h3 id="切趾不是衰减式相移掩模" tabindex="-1">切趾不是衰减式相移掩模 <a class="header-anchor" href="#切趾不是衰减式相移掩模" aria-label="Permalink to &quot;切趾不是衰减式相移掩模&quot;">​</a></h3><p>相移掩模改的是物频谱 \\(T\\)，发生在掩模面。光瞳滤波改的是投影通道的 \\(P\\)，发生在傅里叶面。两者都能压零级或改权重，座位不同。把 attPSM 的透过率叫成切趾，会把物面与光瞳面搅在一起。</p><p><span class="marginnote">照明光瞳的整形（偶极、自由形状源）是源侧的 \\(S(\\mathbf{f})\\)，不是投影 \\(P\\)。本课的滤波乘在成像光瞳上；源如何填窗，是部分相干课的 \\(\\sigma\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写 \\(P(\\rho,\\phi)=A(\\rho,\\phi)\\,e^{ikW}\\)。本课取 \\(W=0\\)，只设计非负振幅 \\(A\\)。常见工程形状：径向渐变（高斯或多项式切趾）、环形通带、中心遮拦。Born &amp; Wolf 把切趾当作衍射积分的权重；Mack 把它读成光刻里可插入的光瞳滤波器——用来改两束 / 三束的相对权重或压相干旁瓣。</p><p>相干成像：像场仍是 \\(\\mathcal{F}^{-1}\\{A\\,T\\}\\)，\\(A\\) 不是砖墙时，等效核变胖、振铃变弱。部分相干时，\\(A\\) 进入 Hopkins 的交叉系数，密图形的调制与孤立线的旁瓣被同一张 \\(A\\) 牵动，不能只看艾里环。</p><p><span class="marginnote">常见误区：以为切趾只是把光调暗。它不是均匀衰减，而是按半径重新分配透过率——有的频率乘大系数、有的乘小系数。均匀变暗只改曝光剂量，切趾改的是衍射核的形状，两码事。</span></p><h3 id="能量与-nils-一起搬家" tabindex="-1">能量与 NILS 一起搬家 <a class="header-anchor" href="#能量与-nils-一起搬家" aria-label="Permalink to &quot;能量与 NILS 一起搬家&quot;">​</a></h3><p>压低光瞳边缘等于少收高频，NILS 通常下降，剂量轴变脆；压低旁瓣则孤立孔、线端更干净。中心遮拦相反：切掉靠近轴的低频通道，对比对某些节距上升，焦深与杂散行为另算。本课不选「最佳 \\(A\\)」；只要求后课写光瞳时允许 \\(|P|\\neq\\mathrm{circ}\\)。</p><p><span class="marginnote">镀膜均匀性、遮拦、pellicle 框架在光瞳上的阴影，都会变成非故意的 \\(A(\\rho)\\)。计量上要把它与故意切趾分开，也与相位像差分开。</span></p>',17)),(i(),o(A,null,{default:e(()=>[n(r,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20TD%0A%20%20ABBE%5B%22%E9%98%BF%E8%B4%9D%EF%BC%9AP%20%E4%B9%98%E9%A2%91%E8%B0%B1%22%5D%20--%3E%20AMP%5B%22%E9%80%9A%E5%B8%A6%E6%8C%AF%E5%B9%85%20A(%CF%81)%22%5D%0A%20%20AMP%20--%3E%20AP%5B%22%E5%88%87%E8%B6%BE%EF%BC%9A%E6%97%81%E7%93%A3%E2%86%93%20%E4%B8%BB%E7%93%A3%E2%86%91%22%5D%0A%20%20AMP%20--%3E%20OBS%5B%22%E9%81%AE%E6%8B%A6%20%2F%20%E8%BE%B9%E7%BC%98%E5%8A%A0%E9%87%8D%22%5D%0A%20%20AP%20--%3E%20KER%5B%22%E8%A1%8D%E5%B0%84%E6%A0%B8%E5%BD%A2%E7%8A%B6%22%5D%0A%20%20OBS%20--%3E%20KER%0A%20%20KER%20--%3E%20NEXT%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9ANA%20%E7%BB%99%E7%AA%97%E6%A0%87%E5%8D%8A%E5%BE%84%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"硬切是矩形窗，频谱卷积出 sinc 环。切趾是把窗乘缓变包络，环的能量被打散，主瓣展宽——与信号处理里的窗函数同一件事，只是窗坐在光瞳上。光刻图形不是单点：周期级落在 \\(A(\\rho)\\) 的不同半径上，切趾等于给各级乘不同透过率，空中像的调制深度改了，阈值处的 ILS 跟着改。",-1)),(i(),o(A,null,{default:e(()=>[n(r,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20HW%5B%22%E7%A1%AC%E5%88%87%E5%85%89%E7%9E%B3%20%3D%20%E7%9F%A9%E5%BD%A2%E7%AA%97%22%5D%20--%3E%20SL%5B%22%E9%A2%91%E8%B0%B1%E5%8D%B7%E7%A7%AF%E5%87%BA%20sinc%20%E7%8E%AF%22%5D%0A%20%20AP%5B%22%E5%88%87%E8%B6%BE%20%3D%20%E4%B9%98%E7%BC%93%E5%8F%98%E5%8C%85%E7%BB%9C%22%5D%20--%3E%20SP%5B%22%E6%97%81%E7%93%A3%E8%83%BD%E9%87%8F%E8%A2%AB%E6%89%93%E6%95%A3%22%5D%0A%20%20AP%20--%3E%20MB%5B%22%E4%B8%BB%E7%93%A3%E5%B1%95%E5%AE%BD%20%E5%88%86%E8%BE%A8%E7%8E%87%E6%8D%A2%E5%B9%B2%E5%87%80%22%5D%0A%20%20SP%20--%3E%20MOD%5B%22%E5%90%84%E7%BA%A7%E6%8C%89%20A(%CF%81)%20%E5%8A%A0%E6%9D%83%22%5D%0A%20%20MB%20--%3E%20MOD%0A%20%20MOD%20--%3E%20ILS%5B%22%E7%A9%BA%E4%B8%AD%E5%83%8F%E8%B0%83%E5%88%B6%E4%B8%8E%20ILS%20%E6%94%B9%E5%8F%98%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=l('<p>故意滤波与像差不同：像差是相位，切趾是损耗或遮拦。两者相乘。把对比下降全部写成「像差变差」，会漏掉光瞳振幅这张图。</p><h3 id="后课默认的接口" tabindex="-1">后课默认的接口 <a class="header-anchor" href="#后课默认的接口" aria-label="Permalink to &quot;后课默认的接口&quot;">​</a></h3><p>说到 \\(P\\)，默认可以带径向振幅，不只是 0/1。\\(\\mathrm{NA}\\) 仍未正式定义，窗的边缘下一课才变成合同上的 \\(n\\sin\\theta\\)；切趾是边缘以内的权重，不是把边缘搬家。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不含可变形镜的相位图，不含 SMO 的源优化。也不要把 EUV 中心遮拦的几何面积当成已经切趾完毕：遮拦是 \\(A\\) 的一种，反射镜相位是 \\(W\\) 的一种。禁止编造未公开的光瞳透过率地图；教科书里的径向权重已经够说明机制。标量 \\(A\\) 在高 \\(\\mathrm{NA}\\) 还要乘矢量投影，定义仍是「通带振幅可调制」。</p><p><span class="marginnote">直觉类比：三处滤波像一台调音台——源整形决定「哪些乐器进来」，切趾给已进来的频段调音量，相移掩模则是在乐谱上改写音符。都影响最终的声音，但动的层次不同，混着说就会诊断错。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>阿贝的硬切只是 \\(A=1\\) 的特例；切趾 / 遮拦调制通带振幅。</li><li>旁瓣与主瓣此消彼长；各级落在不同 \\(\\rho\\) 上，调制被 \\(A\\) 加权。</li><li>切趾在光瞳，相移掩模在物面，源整形在照明瞳，三处不要混名。</li><li>相位像差下一组课再写；\\(|P|\\) 与 \\(W\\) 相乘。</li><li>窗的半径由下一课的 \\(\\mathrm{NA}\\) 标定。</li><li>出处：Born &amp; Wolf, <em>Principles of Optics</em>；Mack, <em>Fundamental Principles of Optical Lithography</em>。</li></ul>',8))])}const b=s(h,[["render",d]]);export{_ as __pageData,b as default};
